// ── BATCH_LIMIT ────────────────────────────────────────────────────────────────────────────
// The ONE place to control how many Quickbase rows are processed AND written per run.
// SHIPPED DEFAULT = 5 for a controlled first write-back.
// After you verify those 5 rows updated correctly in Quickbase, raise this
// (e.g. 1000) — or page through with SKIP — for a full run.
const BATCH_LIMIT = 5;
const SKIP = 0; // pagination offset; for a full run, increase by BATCH_LIMIT per page
return [{ json: { BATCH_LIMIT, SKIP } }];

// Split the Quickbase /records/query response into one item per bill.
// Response shape: { data: [ { "<fid>": { value: ... }, ... } ] }
// QBO realmId is a workflow-level placeholder set ONCE here; it flows to both QBO nodes.
const REALM_ID = 'YOUR_QBO_REALM_ID'; // <-- PLACEHOLDER: QuickBooks Online company realmId

const resp = $input.first().json;
const rows = Array.isArray(resp.data) ? resp.data : [];
const fv = (row, fid) => (row && row[fid] && row[fid].value !== undefined ? row[fid].value : null);

return rows.map((row) => {
  const ref = fv(row, '123'); // Reference # — the match key (= QBO Bill DocNumber)
  // Escape single quotes for the QBO query language by doubling them.
  // Do NOT trim: trailing spaces are part of the stored key and are exactly what we test for.
  const refEscaped = ref === null ? '' : String(ref).replace(/'/g, "''");
  return {
    json: {
      realmId: REALM_ID,
      recordId: fv(row, '3'),              // Record ID#
      ref: ref,                             // Reference # (key used)
      refEscaped: refEscaped,               // escaped for QBO WHERE clause
      billId: fv(row, '76'),                // Bill ID#
      billAmount: fv(row, '49'),            // Bill Amount
      currentStatus: fv(row, '14'),         // Status (current Quickbase value)
      currentAmountPaid: fv(row, '143'),    // Amount Paid (current Quickbase value)
      currentDatePaid: fv(row, '12'),       // Date Paid (current Quickbase value)
      linkedToQuickbooks: fv(row, '154')
    },
    pairedItem: { item: 0 }
  };
});

// Compute Status & Amount Paid from the matched QBO Bill, and collect linked BillPayment IDs.
// Runs once per item. $json = QBO Bill query response; the original Quickbase record is read
// from the Normalize node via the paired item.
const rec = $('Normalize Quickbase Records').item.json;
const qbo = $json || {};

const bills = (qbo.QueryResponse && Array.isArray(qbo.QueryResponse.Bill)) ? qbo.QueryResponse.Bill : [];
const bill = bills[0] || null;

let matchFound = false;
let qboBalance = null;
let qboTotalAmt = null;
let computedStatus = '';
let computedAmountPaid = null;
let paymentIds = [];

if (bill) {
  matchFound = true;
  qboTotalAmt = Number(bill.TotalAmt);
  qboBalance = Number(bill.Balance);
  // Nothing paid (Balance == TotalAmt) -> Unpaid; any payment incl. partial -> Paid.
  // Compare at cent level to avoid float noise.
  const totalCents = Math.round(qboTotalAmt * 100);
  const balCents = Math.round(qboBalance * 100);
  computedStatus = (balCents === totalCents) ? 'Unpaid' : 'Paid';
  computedAmountPaid = (totalCents - balCents) / 100;
  // Collect linked BillPayment transaction IDs.
  const linked = Array.isArray(bill.LinkedTxn) ? bill.LinkedTxn : [];
  paymentIds = linked
    .filter(t => t && t.TxnType === 'BillPayment' && t.TxnId != null)
    .map(t => String(t.TxnId));
}

// Build an IN-clause for the follow-up BillPayment query. No linked payments -> '0' so the
// request is still valid and simply returns an empty QueryResponse.
const hasPayments = paymentIds.length > 0;
const paymentInClause = hasPayments
  ? paymentIds.map(id => `'${id.replace(/'/g, "''")}'`).join(',')
  : "'0'";

return {
  json: {
    realmId: rec.realmId,
    recordId: rec.recordId,
    ref: rec.ref,
    matchFound,
    qboBalance,
    qboTotalAmt,
    computedStatus,
    computedAmountPaid,
    hasPayments,
    paymentIds,
    paymentInClause,
    currentStatus: rec.currentStatus,
    currentAmountPaid: rec.currentAmountPaid,
    currentDatePaid: rec.currentDatePaid
  }
};

// Assemble the final side-by-side comparison row. $json = BillPayment query response;
// computed values come from the earlier compute node via the paired item.
const computed = $('Compute Status, Amount Paid & Extract Payment IDs').item.json;
const payResp = $json || {};

const payments = (payResp.QueryResponse && Array.isArray(payResp.QueryResponse.BillPayment))
  ? payResp.QueryResponse.BillPayment : [];

// Date Paid = latest TxnDate among linked bill payments (QBO TxnDate is yyyy-MM-dd, so lexical
// sort gives the latest). Blank if none.
let computedDatePaid = '';
if (computed.hasPayments && payments.length > 0) {
  const dates = payments.map(p => p.TxnDate).filter(Boolean).sort();
  computedDatePaid = dates.length ? dates[dates.length - 1] : '';
}

return {
  json: {
    recordId: computed.recordId,
    ref: computed.ref,                         // the match key tested (Reference # / DocNumber)
    matchFound: computed.matchFound,
    qboBalance: computed.qboBalance,
    qboTotalAmt: computed.qboTotalAmt,
    computedStatus: computed.computedStatus,
    computedAmountPaid: computed.computedAmountPaid,
    computedDatePaid: computedDatePaid,
    currentStatus: computed.currentStatus,
    currentAmountPaid: computed.currentAmountPaid,
    currentDatePaid: computed.currentDatePaid
  }
};

// Build the Quickbase bulk-upsert payload from matched rows only.
// Merge key = field 3 (Record ID#) so writes UPDATE existing rows (never create).
// Chunked to <= 100 records per request (Quickbase bulk-upsert safety cap).
const CHUNK_SIZE = 100;
const rows = [];

for (const it of $input.all()) {
  const r = it.json;
  if (r.matchFound !== true) continue; // guard: never write unmatched rows

  const record = {
    "3":   { value: r.recordId },            // Record ID# — merge/upsert key (keyFieldId=3)
    "14":  { value: r.computedStatus },      // Status: exactly "Paid" or "Unpaid"
    "143": { value: r.computedAmountPaid }   // Amount Paid (currency)
  };

  // Date Paid (field 12, timestamp): include ONLY when a payment date exists.
  // Omit entirely when blank so an existing Quickbase value is NOT wiped out.
  // field 12 is a timestamp -> send ISO 8601. Noon UTC avoids the calendar date
  // shifting a day earlier when Quickbase renders in a US timezone.
  if (r.computedDatePaid) {
    record["12"] = { value: `${r.computedDatePaid}T12:00:00Z` };
  }

  rows.push({
    record,
    _audit: {
      recordId: r.recordId,
      ref: r.ref,
      status: r.computedStatus,
      amountPaid: r.computedAmountPaid,
      datePaid: r.computedDatePaid || null
    }
  });
}

const out = [];
for (let i = 0; i < rows.length; i += CHUNK_SIZE) {
  const chunk = rows.slice(i, i + CHUNK_SIZE);
  out.push({
    json: {
      chunkIndex: out.length,
      to: "bum6mrfti",
      data: chunk.map(c => c.record),
      fieldsToReturn: [3, 14, 143, 12],
      _written: chunk.map(c => c._audit)
    }
  });
}
// If nothing matched, emit nothing; Summarize still reports skipped via the Assemble node.
return out;

// Summarize the write-back: what was updated, what was skipped (no match), and any errors.
const responses = $input.all(); // one item per upsert chunk (empty if nothing matched)

// Rows we attempted to write (from the payload builder, across all chunks)
let attempted = [];
try {
  for (const b of $('Build Upsert Payload (matched rows)').all()) {
    attempted = attempted.concat(b.json._written || []);
  }
} catch (e) { /* builder produced no items */ }

// Rows skipped because no QBO match was found (never written).
const skipped = $('Assemble Comparison Output').all()
  .map(a => a.json)
  .filter(r => r.matchFound !== true)
  .map(r => ({ recordId: r.recordId, ref: r.ref }));

let updatedCount = 0;
const unchangedRecordIds = [];
const lineErrors = [];

responses.forEach((resp, idx) => {
  const body = resp.json || {};
  // onError=continue may surface an error object instead of a normal response.
  if (body.error || (body.message && !body.metadata)) {
    lineErrors.push({ chunk: idx, error: body.error || body.message });
    return;
  }
  const meta = body.metadata || {};
  updatedCount += (meta.updatedRecordIds || []).length;
  (meta.unchangedRecordIds || []).forEach(id => unchangedRecordIds.push(id));
  if (meta.lineErrors && typeof meta.lineErrors === 'object') {
    for (const [line, errs] of Object.entries(meta.lineErrors)) {
      lineErrors.push({ chunk: idx, line, errors: errs });
    }
  }
});

return [{
  json: {
    summary: {
      matchedAttempted: attempted.length,
      updated: updatedCount,
      unchanged: unchangedRecordIds.length,
      skippedNoMatch: skipped.length,
      lineErrorCount: lineErrors.length
    },
    updatedRecords: attempted,
    skipped,
    unchangedRecordIds,
    lineErrors
  }
}];

